BEGIN;


COMMIT;

SELECT c.codigo, crc.*
FROM  ensino_infantil.configuracao_relatorio c
JOIN ensino_infantil.configuracao_relatorio_componente crc ON crc.id_configuracao_relatorio  = c.id_configuracao_relatorio
WHERE crc.id_configuracao_relatorio IN (5,6,4)
AND crc.id_componente_curricular <> 293
ORDER BY crc.id_configuracao_relatorio ;
